--toolbarbutton-default-active-boxshadow: rgba(0, 0, 0, 0.1) inset, 0 0 1px rgba(0, 0, 0, 0.3);
--toolbarbutton-active-boxshadow: light-dark(0 1px 1px var(--lwt-toolbarbutton-active-background, var(--toolbarbutton-default-active-boxshadow)) inset, none);
--toolbarbutton-checked-background: light-dark(var(--lwt-toolbarbutton-hover-background, rgba(200, 200, 200, 0.5)), rgba(0, 0, 0, 0.25));
--toolbarbutton-icon-fill-attention: var(--lwt-toolbarbutton-icon-fill-attention, var(--selected-item-color));
--toolbarseparator-color: var(--color-surface-border);
--panel-separator-color: var(--color-surface-border);
--toolbar-field-color: var(--layout-color-1);
--toolbar-field-background-color: var(--layout-background-1);
--toolbar-field-focus-border-color: var(--selected-item-color);
--toolbar-field-highlight: var(--selected-item-color);
--toolbar-field-highlight-color: var(--selected-item-text-color);
--item-focus-selected-border-color: light-dark(#0060df, #bebebf);
